      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "STS-E412, a triazolopyrimidine analogue, was BBB-permeable in rats with a brain/plasma ratio of 0.39 after intraperitoneal dosing, confirming CNS access despite modest total brain distribution.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Praziquantel, a lipophilic neutral heteroaromatic drug, penetrates rapidly into human CSF, supporting that this physicochemical class can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
